def link_managers(apps, schema_editor):
    """Match each profile's free-text manager to an employee record.

    Matched rows get manager_email. Unmatched or ambiguous names are left
    blank and appear in GET /api/org/manager-review for HR to resolve."""
    UserProfile = apps.get_model('api', 'UserProfile')
    AppUser = apps.get_model('api', 'AppUser')
    names = {}
    def add(name, email):
        key = ' '.join(str(name or '').split()).lower()
        if key:
            names.setdefault(key, set()).add(str(email).strip().lower())
    for u in AppUser.objects.all():
        add(u.full_name, u.email)
    for p in UserProfile.objects.all():
        add(f'{p.first_name} {p.last_name}', p.email)
    emails = {str(e).strip().lower() for e in AppUser.objects.values_list('email', flat=True)}
    emails |= {str(e).strip().lower() for e in UserProfile.objects.values_list('email', flat=True)}
    for p in UserProfile.objects.exclude(manager='').filter(manager_email=''):
        text = ' '.join(p.manager.split())
        me = p.email.strip().lower()
        hit = ''
        if '@' in text and text.lower() in emails:
            hit = text.lower()
        else:
            cands = names.get(text.lower(), set())
            if len(cands) == 1:
                hit = next(iter(cands))
        if hit and hit != me:
            p.manager_email = hit
            p.save(update_fields=['manager_email'])


